import navigation from '../data/generated/navigation.json';
import changelog from '../data/generated/changelog.json';
import audit from '../../audit/latest.json';
import generated from '../data/generated/site.json';

export const SITE = {
  /** Generated by tools/site_export.py from world.config.yaml — edit the config, not this file. */
  name: generated.name,
  worldId: generated.worldId,
  slug: generated.slug,
  tagline: generated.tagline,
  description: generated.description,
  /** The credit line and copyright holder. */
  author: generated.author,
  license: generated.license,
  /** The site's URL: used for absolute links in the feed and the social card. */
  url: generated.url,
  /** Buttondown username; REPLACE_ME in world.config.yaml until the account exists. */
  buttondownUser: generated.buttondownUser,
  /** Hero art: drop a file in site/public/img/ and describe it in world.config.yaml. */
  heroAlt: generated.heroAlt,
  /** Shown small under the hero when the art is someone else's; empty when it is ours. */
  heroCredit: generated.heroCredit,
  /** The hero image's basename in public/img/, without an extension. */
  heroFile: generated.heroFile,
  /** The search box's hint: the world supplies examples from its own vocabulary. */
  searchPlaceholder: generated.searchPlaceholder,
  /** The engine's content descriptors, as the world declares them. */
  contentDescriptors: generated.contentDescriptors,
  /** The year-zero prefix and the name the world gives it ("T0", "the Severing"). */
  t0Prefix: generated.t0Prefix,
  t0Epoch: generated.t0Epoch,
};
/** A navigation section: the world's slug, label, count and one-line blurb. */
export type Section = { slug: string; label: string; count: number; blurb?: string };

export const sections: Section[] = navigation as Section[];

export const codexUpdated: string = (audit as { generated: string }).generated;

export type ChangeEntry = {
  date: string;
  change: 'added' | 'updated';
  id: string;
  title: string;
  section: string;
  slug: string;
};

export const changelogEntries: ChangeEntry[] = changelog as ChangeEntry[];

export function sectionLabel(slug: string): string {
  return sections.find((s) => s.slug === slug)?.label ?? slug;
}

/** Alphabetical, ignoring a leading article (so "The Choir" files under C). */
export function sortKey(title: string): string {
  return title.replace(/^(the|a|an)\s+/i, '').toLowerCase();
}

/** The numeric year offset of a page's `t0` (T0 = the Severing); null when undated. */
export function t0Number(t0?: string): number | null {
  if (!t0) return null;
  const value = Number(t0);
  return Number.isFinite(value) ? value : null;
}

/**
 * "<prefix> −5,100", "<prefix> +40", "<prefix>". The sign hugs the number so a negative offset
 * reads as a negative number, and the typographic minus matches the vault's own prose. The prefix
 * and what the zero means come from the world's config, not from here. Null when undated.
 */
export function formatT0(t0?: string): string | null {
  const value = t0Number(t0);
  if (value === null) return t0 ? `${SITE.t0Prefix} ${t0}` : null;
  if (value === 0) return SITE.t0Prefix;
  const sign = value < 0 ? '−' : '+';
  return `${SITE.t0Prefix} ${sign}${Math.abs(value).toLocaleString('en-GB')}`;
}

/**
 * Section order: chronological where the pages are dated (oldest first, undated pages after the
 * dated ones), alphabetical otherwise. Ties break on the title, so the order is stable.
 */
export function byTimeThenTitle(
  a: { data: { t0?: string; title: string } },
  b: { data: { t0?: string; title: string } },
): number {
  const ta = t0Number(a.data.t0);
  const tb = t0Number(b.data.t0);
  if (ta !== null && tb !== null && ta !== tb) return ta - tb;
  if (ta === null && tb !== null) return 1;
  if (ta !== null && tb === null) return -1;
  return sortKey(a.data.title).localeCompare(sortKey(b.data.title), 'en');
}

export function formatDate(iso: string): string {
  const date = new Date(`${iso}T00:00:00Z`);
  if (Number.isNaN(date.getTime())) return iso;
  return date.toLocaleDateString('en-GB', {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
    timeZone: 'UTC',
  });
}

/** The exporter emits inline markdown in summaries (links and bold). Render just that much. */
export function inline(md: string): string {
  const escaped = md
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
  return escaped
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
}

export function urlFor(section: string, slug: string): string {
  return `/${section}/${slug}/`;
}

/**
 * How a world's tags read. Which tags publish is the exporter's decision (the world's
 * `site-vocabulary` block, site.md section 3.3); how each one is *named* is the world's copy, and
 * it arrives here generated. A tag with no label falls back to its title-cased slug, so a world
 * that declares none still reads sensibly.
 */
const TAG_LABELS: Record<string, string> = generated.tagLabels;

/** The URL segment for a tag, shared by the chip and the route so they cannot disagree. */
export function tagSlug(tag: string): string {
  return tag
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

export function tagLabel(tag: string): string {
  const known = TAG_LABELS[tag];
  if (known) return known;
  return tag
    .split('-')
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

export function tagHref(tag: string): string {
  return `/tags/${tagSlug(tag)}/`;
}

/** The landing page's navigation cards: the world's, from `world.config.yaml`. */
export const doorways = generated.doorways;

/** The player-facing tone statement; also on /about/. The world writes it (its `## What to expect`). */
export const whatToExpect = generated.whatToExpect;

export const contentDescriptors = SITE.contentDescriptors;
